TLM.f("Sancti/10-25",{"officium":"Ss. Chrysanthi et Dariæ Martyrum","rule":["vide C3;","Suffragium=Maria3;Papa;Ecclesia;;"],"fallback":"Commune/C3","from":{"Introitus":"Commune/C3","Lectio":"Commune/C3","Graduale":"Commune/C3","Tractus":"Commune/C3","Offertorium":"Commune/C3","Communio":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Beatórum Mártyrum tuórum, Dómine, Chrysánthi et Daríæ, quǽsumus, adsit nobis orátio: ut, quos venerámur obséquio, eórum pium júgiter experiámur auxílium."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 3:1-8"},{"k":"text","la":"Justorum ánimæ in manu Dei sunt, et non tanget illos torméntum mortis. Visi sunt oculis insipiéntium mori: et æstimála est afflíctio exitus illórum: et quod a nobis est iter, extermínium: illi autem sunt in pace. Et si coram homínibus torménta passi sunt, spes illórum immortalitáte plena est. In paucis vexáti, in multis bene disponéntur: quóniam Deus tentávit eos, et invenit illos dignos se. Tamquam aurum in fornáce probávit illos, et quasi holocáusti hóstiam accépit illos, et in témpore erit respéctus illorum. Fulgébunt justi, et tamquam scintíllæ in arundinéto discúrrent. Judicábunt natiónes, et dominabúntur pópulis, et regnábit Dóminus illórum in perpétuum."}],"Graduale":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Eccl 44:14"},{"k":"text","la":"Córpora Sanctórum in pace sepúlta sunt, et nómina eórum vivent in generatiónem et generatiónem. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc. 11:47-51"},{"k":"text","la":"In illo témpore: Dicébat Jesus scribis et pharisǽis: Væ vobis, qui ædificátis monuménta prophetárum: patres autem vestri occidérunt illos. Profécto testificámini, quod consentítis opéribus patrum vestrórum: quóniam ipsi quidem eos occidérunt, vos autem ædificátis eórum sepúlcra. Proptérea et sapiéntia Dei dixit: Mittam ad illos prophétas et apóstolos, et ex illis occídent et persequántur: ut inquirátur sanguis ómnium prophetárum, qui effúsus est a constitutióne mundi a generatióne~ ista, a sánguine Abel usque ad sánguinem Zacharíæ, qui périit inter altáre et ædem. Ita dico vobis, requirétur ab hac generatióne."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Pópuli tui, quǽsumus, Dómine, tibi grata sit hóstia, quæ in natalítiis sanctórum Mártyrum tuórum Chrysánthi et Daríæ sollémniter immolátur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:4-6"},{"k":"text","la":"Et si coram homínibus torménta passi sunt, Deus tentávit eos: tamquam aurum in fornáce probávit eos, et quasi holocáusta accépit eos."}],"Postcommunio":[{"k":"text","la":"Mýsticis, Dómine, repléti sumus votis et gáudiis: præsta, quǽsumus; ut, intercessiónibus sanctórum Mártyrum tuórum Chrysánthi et Daríæ, quæ temporáliter ágimus, spirituáliter consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"e05d3e95831ee10d":{"t":"<i>Pomolimo se</i>.\nNeka bude uz nas, molimo, Gospodine, molitva blaženih mučenika tvojih Krizanta i Darije da neprestano osjećamo dobrostivu pomoć onih koje častimo ovom službom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"2fc5d373303241e9":{"t":"Bio ti mio, molimo. Gospodine, dar tvoga naroda, koji ti svečano prinosimo o rođendanu svetih mučenika tvojih Krizanta i Darije.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e8455f32fea7aa6d":{"t":"<i>Pomolimo se</i>.\nNasitili smo se, Gospodine, otajstvenim darovima i radostima, pa te molimo, daj da po zagovoru svetih mučenika tvojih Krizanta i Darije duhovno postignemo što u vremenitoj svečanosti obavljamo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
